const ICONIFY_SI_KEY: Record<string, string> = {
  'amazon': 'amazon',
  'canva': 'canva',
  'microsoftteams': 'microsoftteams',
  'nexusmods': 'nexusmods',
  'pocket': 'pocket',
  'primevideo': 'primevideo',
  'walmart': 'walmart',
  'xbox': 'xbox',
}

export function resolveBrandLogo(toolId: string): ResolvedBrandLogo | null {
  const s = SIMPLE[toolId]
  if (s) return { kind: 'simple', icon: s }

  const logosKey = ICONIFY_KEY[toolId]
  if (logosKey) {
    const ic = logosIcons[logosKey]
    if (ic) {
      return { kind: 'iconify', body: ic.body, viewBox: iconifyViewBox(logosKey, ic, 'logos') }
    }
  }

  const direct = logosIcons[toolId]
  if (direct) {
    return { kind: 'iconify', body: direct.body, viewBox: iconifyViewBox(toolId, direct, 'logos') }
  }

  const siSlug = ICONIFY_SI_KEY[toolId]
  if (siSlug) {
    const ic = siIconifyIconsBundled[siSlug]
    if (ic) {
      return { kind: 'iconify', body: ic.body, viewBox: iconifyViewBox(siSlug, ic, 'si') }
    }
  }

  return null
}
